const legacyStages=['Tender','Tender – High Probability','In Hand','Negotiation','Closed Won','Closed Lost'];
function legacyStage(p){
  if(!p)return 'Tender';
  if(p.sales_stage && legacyStages.includes(p.sales_stage))return p.sales_stage;
  if(p.status==='won')return 'Closed Won';
  if(p.status==='lost'||p.status==='cancelled')return 'Closed Lost';
  if(p.status==='negotiation')return 'Negotiation';
  if(p.project_type==='in_hand')return 'In Hand';
  if(p.project_type==='tender_in_market' && Number(p.win_probability||0)>50)return 'Tender – High Probability';
  return 'Tender';
}
function allowedLegacyStages(current){
  const s=legacyStages.includes(current)?current:'Tender';
  if(s==='Closed Won'||s==='Closed Lost')return [s];
  if(s==='Negotiation')return ['Negotiation','Closed Won','Closed Lost'];
  if(s==='In Hand')return ['In Hand','Negotiation','Closed Won','Closed Lost'];
  if(s==='Tender – High Probability')return ['Tender – High Probability','In Hand','Negotiation','Closed Won','Closed Lost'];
  return legacyStages;
}
