 async function save(type,f){
  try{
   let r;
   if(type==='company')r=await supabase.from('companies').insert({...f,created_by:profile?.id||null}).select().single();
   if(type==='contact')r=await supabase.from('contacts').insert(f).select().single();
   if(type==='project'){
     const {status,lost_reason,sales_stage,...rest}=f;
     const payload={...rest,estimated_value:f.estimated_value?Number(f.estimated_value):null,win_probability:Number(f.win_probability||0),updated_at:new Date().toISOString()};
     if(f.id){
       const current=projects.find(x=>x.id===f.id);
       r=await supabase.from('projects').update(payload).eq('id',f.id).select().single();
       if(!r.error&&f.status&&f.status!==current?.status) await transitionProjectStatus(f);
       if(!r.error&&f.sales_stage&&f.sales_stage!==legacyStage(current)) {
         const sr=await supabase.rpc('set_sales_stage',{p_project_id:f.id,p_sales_stage:f.sales_stage});
         if(sr.error)throw sr.error;
       }
       if(!r.error&&f.sales_stage==='Closed Won'){
         if(!f.contract_date || f.contract_value==='' || isNaN(Number(f.contract_value))) throw new Error('Closed Won requires Contract Date and Contract Value.');
         const existing=contracts.find(c=>c.project_id===f.id);
         const cr=existing
           ? await supabase.from('contracts').update({contract_date:f.contract_date,contract_value:Number(f.contract_value),updated_at:new Date().toISOString()}).eq('id',existing.id).select().single()
           : await supabase.from('contracts').insert({project_id:f.id,contract_date:f.contract_date,contract_value:Number(f.contract_value),currency:f.currency||'EGP',status:'active',created_by:profile?.id||null}).select().single();
         if(cr.error)throw cr.error;
       }
     }else{
       r=await supabase.from('projects').insert({...payload,status:f.status||'new',sales_stage:f.sales_stage||'Tender',lost_reason:f.lost_reason||null,sales_owner_id:f.sales_owner_id||profile?.id||null,created_by:f.created_by||profile?.id||null}).select().single();
     }
   }
   if(type==='followup'){const p=projects.find(x=>x.id===f.project_id);const {next_follow_up_type,...fu}=f;r=await supabase.from('follow_ups').insert({...fu,follow_up_type:f.follow_up_type||'phone_call',company_id:p?.company_id,responsible_id:profile?.id||null}).select().single()}   if(type==='technical')r=await supabase.from('technical_requests').insert({...f,requested_by:profile?.id||null}).select().single();
   if(type==='quotation'){const versions=quotations.filter(q=>q.project_id===f.project_id);r=await supabase.from('quotations').insert({...f,version_no:versions.length+1,prepared_by:profile?.id||null,value:Number(f.value||0)}).select().single();}
   if(type==='collection')r=await supabase.from('collections').insert({...f,amount:Number(f.amount||0),recorded_by:profile?.id||null}).select().single();
   if(type==='contract')r=await supabase.from('contracts').insert({...f,contract_value:Number(f.contract_value||0),created_by:profile?.id||null}).select().single();
   if(r.error)throw r.error;
   const auditMap={company:['CREATE_CLIENT','Company'],contact:['CREATE_CONTACT','Contact'],project:[f.id?'UPDATE_PROJECT':'CREATE_PROJECT','Project'],followup:['CREATE_FOLLOW_UP','Follow Up'],technical:['CREATE_TECHNICAL_REQUEST','Technical Request'],quotation:['CREATE_QUOTATION','Quotation'],collection:['CREATE_COLLECTION','Collection'],contract:['CREATE_CONTRACT','Contract']};
   const [auditAction,auditEntity]=auditMap[type]||['UPDATE','Record'];
   const auditId=r.data?.id||f.id||null;
   const ar=await supabase.from('audit_log').insert({actor_id:profile?.id||null,action:auditAction,entity_type:auditEntity,entity_id:auditId,details:f});
   if(ar.error)throw ar.error;
   setModal(null);notify('Saved successfully');await load();
  }catch(e){setError(e.message||'Save failed')}
 }
